parameters.command:
cd /work/output/artifacts/skill-flow-transform-group-by/TransformGroupByDemo/TransformGroupByDemo

# Save registry definitions
uip maestro flow registry get core.action.script --output json > /tmp/def_script.json
uip maestro flow registry get core.action.transform.group-by --output json > /tmp/def_groupby.json
uip maestro flow registry get core.control.end --output json > /tmp/def_end.json

# Write the edit plan
cat > /tmp/plan_groupby.json << 'PLAN'
{
  "ops": [
    {
      "op": "add-node",
      "id": "emitEmployees",
      "type": "core.action.script",
      "definitionFile": "/tmp/def_script.json",
      "label": "Emit Employees",
      "inputs": {
        "script": "return { items: [{ name: 'Alice', department: 'Engineering', salary: 95000 }, { name: 'Bob', department: 'Marketing', salary: 72000 }, { name: 'Carol', department: 'Engineering', salary: 110000 }, { name: 'Dave', department: 'Marketing', salary: 68000 }, { name: 'Eve', department: 'Engineering', salary: 88000 }] };"
      }
    },
    {
      "op": "add-node",
      "id": "groupByDept",
      "type": "core.action.transform.group-by",
      "definitionFile": "/tmp/def_groupby.json",
      "label": "Group by Department",
      "inputs": {
        "collection": "$vars.emitEmployees.output.items",
        "operations": [
          {
            "id": "op1",
            "type": "groupBy",
            "config": {
              "groupByField": "department",
              "aggregations": [
                { "id": "a1", "field": "", "operation": "count", "alias": "headcount" },
                { "id": "a2", "field": "salary", "operation": "sum", "alias": "totalSalary" },
                { "id": "a3", "field": "salary", "operation": "average", "alias": "avgSalary" }
              ]
            }
          }
        ]
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the transform",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the transform fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "op": "add-node",
      "id": "end",
      "type": "core.control.end",
      "definitionFile": "/tmp/def_end.json",
      "label": "End",
      "outputs": "none"
    },
    {
      "op": "add-edge",
      "source": "start",
      "sourcePort": "output",
      "target": "emitEmployees",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "emitEmployees",
      "sourcePort": "success",
      "target": "groupByDept",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "groupByDept",
      "sourcePort": "output",
      "target": "end",
      "targetPort": "input"
    },
    {
      "op": "add-variable",
      "id": "groupedResult",
      "direction": "out",
      "type": "object",
      "description": "Grouped department salary statistics"
    },
    {
      "op": "add-output-mapping",
      "endNode": "end",
      "var": "groupedResult",
      "source": "=js:$vars.groupByDept.output"
    }
  ]
}
PLAN

python3 /home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow/scripts/flow_edit.py apply \
  --flow TransformGroupByDemo.flow \
  --plan /tmp/plan_groupby.json
